"Aqui só entram os lembretes com data até hoje. Com hora marcada, avisa-te mesmo com a app fechada se estiveres em jogo; se não estiveres, quando voltares (até 12 h depois). Fica guardado neste telemóvel.": "Seuls les rappels datés d'aujourd'hui ou avant apparaissent ici. Avec une heure définie, vous êtes prévenu même si l'app est fermée si vous êtes en jeu ; sinon, à votre retour (jusqu'à 12 h plus tard). Enregistré sur ce téléphone.",
