"Compra e vende veículos, casas e mais. Carros, casas e tudo o resto, num toque.": "Achetez et vendez des véhicules, des maisons et plus encore. Voitures, maisons et tout le reste, en un geste.",
"Conhece pessoas em Los Santos. Desliza, combina, conversa.": "Rencontrez des gens à Los Santos. Faites glisser, matchez, discutez.",
"Pede polícia, EMS, mecânico, táxi e mais. Pede ajuda com a tua localização.": "Appelez la police, les urgences, un mécano, un taxi et plus encore. Demandez de l'aide avec votre position.",
"O clássico. Come, cresce e não te mordas. A cada cinco frutas fica mais rápido, e podes jogar com ou sem paredes. O clássico. Come, cresce e não te mordas. A cada cinco frutas fica mais rápido, e podes jogar com ou sem paredes.": "Le classique. Mangez, grandissez et ne vous mordez pas. Tous les cinq fruits, ça accélère, et vous pouvez jouer avec ou sans murs. Le classique. Mangez, grandissez et ne vous mordez pas. Tous les cinq fruits, ça accélère, et vous pouvez jouer avec ou sans murs.",
"Parte todos os tijolos sem deixar cair a bola. Tem tijolos resistentes, bónus que caem e níveis sem fim. Parte todos os tijolos sem deixar cair a bola. Tem tijolos resistentes, bónus que caem e níveis sem fim.": "Cassez toutes les briques sans laisser tomber la balle. Briques résistantes, bonus qui tombent et niveaux sans fin. Cassez toutes les briques sans laisser tomber la balle. Briques résistantes, bonus qui tombent et niveaux sans fin.",
"Os teus veículos, localização e garagem. Localiza, favorita, dá alcunhas.": "Vos véhicules, leur position et votre garage. Localisez-les, mettez-les en favori, donnez-leur des surnoms.",
"Salas anónimas por alcunha. As mensagens ficam guardadas no servidor. Por alcunha. As mensagens ficam no servidor.": "Salons anonymes par pseudo. Les messages sont conservés sur le serveur. Par pseudo. Les messages restent sur le serveur.",
"Descobre o campo sem tocar numa mina. Três dificuldades, modo bandeira e abertura automática à volta dos números. Descobre o campo sem tocar numa mina. Três dificuldades, modo bandeira e abertura automática à volta dos números.": "Déminez le terrain sans toucher une mine. Trois niveaux de difficulté, mode drapeau et ouverture automatique autour des chiffres. Déminez le terrain sans toucher une mine. Trois niveaux de difficulté, mode drapeau et ouverture automatique autour des chiffres.",
"Todos os jogos do telemóvel num sítio só, com os teus recordes e o último que jogaste. Todos os jogos do telemóvel num sítio só, com os teus recordes e o último que jogaste.": "Tous les jeux du téléphone au même endroit, avec vos records et le dernier auquel vous avez joué. Tous les jeux du téléphone au même endroit, avec vos records et le dernier auquel vous avez joué.",
"Assistente com IA: dúvidas sobre o servidor e o telemóvel, contas, tempo e mais. Assistente com IA: dúvidas sobre o servidor e o telemóvel, contas, tempo e mais.": "Assistant IA : questions sur le serveur et le téléphone, calculs, météo et plus encore. Assistant IA : questions sur le serveur et le téléphone, calculs, météo et plus encore.",
