"No ESX, sair de serviço troca o emprego para prefixo + emprego (ex.: offpolice) com o mesmo grau. Vazio: no ESX o serviço fica com o servidor.": "Sous ESX, quitter le service change le métier en préfixe + métier (ex. : offpolice) avec le même grade. Vide : sous ESX, le service est géré par le serveur.",
